import type { Metadata } from 'next';
import Navbar from '@/components/navbar';
import { Footer } from '@/components/footer';
import { CodeBlock } from '@/components/code-block';

/*
 * The evidence page. Deliberately quiet: no animation, no emphasis colour on
 * our own row, nothing that would make the numbers feel sold rather than
 * reported. Every figure is transcribed from bench/RESULTS.md, which is
 * generated by bench/run.mjs.
 */

const REPO = 'https://github.com/mickelsamuel/migrationpilot';
const RESULTS = `${REPO}/blob/main/bench/RESULTS.md`;
const GENERATED = '12 August 2026';

export const metadata: Metadata = {
  title: 'Benchmark: MigrationPilot',
  description:
    'MigrationPilot against Squawk and pgfence on 56 labelled migrations: 31/33 hazards named, 1/17 false positives. Corpus, method, misses and the reproduce command.',
  alternates: { canonical: '/benchmark' },
};

const HEADLINE = [
  { tool: 'MigrationPilot', strict: '31/33', strictPct: '93.9%', loose: '32/33', fp: '1/17', fpPct: '5.9%', gaps: '1/56' },
  { tool: 'Squawk', strict: '20/33', strictPct: '60.6%', loose: '24/33', fp: '1/17', fpPct: '5.9%', gaps: '0/56' },
  { tool: 'pgfence', strict: '25/33', strictPct: '75.8%', loose: '28/33', fp: '3/17', fpPct: '17.6%', gaps: '3/56' },
];

const CORPUS = [
  { name: 'unsafe/', files: '26', verdict: 'dangerous', what: 'One primary named hazard per file, drawn from handbook entries MPH-001 to MPH-020' },
  { name: 'safe/', files: '16', verdict: 'safe', what: "The handbook's own safe SQL. Expand/contract, NOT VALID, CONCURRENTLY. False-positive bait" },
  { name: 'context/', files: '6', verdict: 'context-dependent', what: 'Real hazards that are harmless at the stated scale. Not scored in either direction' },
  { name: 'agent-flavored/', files: '8', verdict: '7 dangerous, 1 safe', what: 'Multi-statement migrations in the register coding agents actually emit' },
];

const VERSIONS = [
  { tool: 'MigrationPilot', version: 'v1.6.0 (6935628)', invocation: 'node dist/cli.cjs analyze <file> --format json --offline --pg-version <v>' },
  { tool: 'Squawk', version: '2.62.0', invocation: 'npx squawk-cli@2.62.0 --reporter json --pg-version <v>.0 <files...>' },
  { tool: 'pgfence', version: '0.6.1', invocation: 'npx @flvmnt/pgfence@0.6.1 analyze --output json --format sql --min-pg-version <v> <files...>' },
];

const MISSES = [
  { file: 'a02-order-status-enum.sql', hazard: 'unbatched-backfill', handbook: 'MPH-010, MPH-018' },
  { file: 'a04-soft-delete.sql', hazard: 'ddl-plus-backfill-same-txn', handbook: 'MPH-016, MPH-018, MPH-003' },
  { file: 'a04-soft-delete.sql', hazard: 'unbatched-backfill', handbook: 'MPH-016, MPH-018, MPH-003' },
  { file: 'u18-ddl-and-backfill-same-transaction.sql', hazard: 'ddl-plus-backfill-same-txn', handbook: 'MPH-016' },
];

const REPRODUCE = `git clone https://github.com/mickelsamuel/migrationpilot
cd migrationpilot && pnpm install && pnpm build
node bench/run.mjs`;

export default function BenchmarkPage() {
  return (
    <>
      <Navbar active="benchmark" />
      <main className="pt-14">
        <section className="pb-2 pt-16 md:pt-20">
          <div className="mp-container">
            <h1 className="max-w-2xl text-[32px] font-semibold leading-[1.15] tracking-tight text-fg sm:text-[40px]">
              Measured against Squawk and pgfence
            </h1>
            <p className="mt-5 max-w-2xl text-base leading-relaxed text-muted">
              56 labelled migration files, three linters, default configuration. Built and published
              by the author of one of the three, which is a conflict of interest, so everything that
              could be used to rig the result is written down and the corpus ships in the
              repository.
            </p>
            <p className="mt-3 font-mono text-xs text-faint">
              Generated {GENERATED} by bench/run.mjs. Platform win32, Node v24.13.0.
            </p>
          </div>
        </section>

        <Block title="Results">
          <Table
            head={['Tool', 'Hazards named', 'Any hazard flagged', 'False positives', 'Unparseable']}
            rows={HEADLINE.map((row) => [
              row.tool,
              `${row.strict} (${row.strictPct})`,
              row.loose,
              `${row.fp} (${row.fpPct})`,
              row.gaps,
            ])}
          />
          <p className="mt-5 max-w-3xl text-[13px] leading-relaxed text-muted">
            Detection is over the 33 dangerous files; false positives are over the 17 safe ones.
            &ldquo;Hazards named&rdquo; is the strict measure: the tool has to name the specific
            hazard the file was written to contain, not merely flag the file. &ldquo;Any hazard
            flagged&rdquo; is the looser one, which needs almost no rule mapping and is therefore
            the hardest number to rig. MigrationPilot finds the most, and ties with Squawk for the
            fewest false positives.
          </p>
        </Block>

        <Block title="How the corpus was built">
          <Table
            head={['Category', 'Files', 'Verdict', 'What it tests']}
            rows={CORPUS.map((row) => [row.name, row.files, row.verdict, row.what])}
          />
          <p className="mt-5 max-w-3xl text-[13px] leading-relaxed text-muted">
            The corpus is derived from the handbook, not from the rule list: each file cites the
            handbook entry whose hazard it exhibits. Hazards MigrationPilot does not catch stay in
            the corpus and are reported as misses below. Ground truth lives in a YAML header in each
            file, so changing a label shows up in the diff. The 33 dangerous files assert 46 (file,
            hazard) pairs across 25 distinct hazard classes.
          </p>
        </Block>

        <Block title="What MigrationPilot missed">
          <Table
            head={['File', 'Hazard missed', 'Handbook', 'Caught by']}
            rows={MISSES.map((row) => [row.file, row.hazard, row.handbook, 'nobody'])}
          />
          <p className="mt-5 max-w-3xl text-[13px] leading-relaxed text-muted">
            Four misses across three files, and no tool in the comparison caught any of them. Two
            hazard classes account for all four: unbatched backfills, and DDL sharing a transaction
            with a backfill. Both are open.
          </p>
          <p className="mt-3 max-w-3xl text-[13px] leading-relaxed text-muted">
            These rows are (file, hazard) pairs, which is why three files produce four of them and
            why the count does not line up with the 31/33 above. That figure is scored per file: 31
            of the 33 dangerous files had the hazard they were written to contain named. The 33
            files assert 46 pairs between them, so a file carrying several hazards can miss one and
            still be counted as detected.
          </p>
        </Block>

        <Block title="The build that was tested">
          <Table
            head={['Tool', 'Version', 'Invocation']}
            rows={VERSIONS.map((row) => [row.tool, row.version, row.invocation])}
            mono
          />
          <p className="mt-5 max-w-3xl text-[13px] leading-relaxed text-muted">
            All three run with their default rule sets: nothing enabled, disabled or configured.
            That is what a team gets on the day they install the tool, and it is the only
            configuration comparable across three products with different opinions about defaults.
            Every tool targets PostgreSQL 17, except on the one corpus file that declares 18 in its
            header, where all three are told 18.
          </p>
          <p className="mt-3 max-w-3xl text-[13px] leading-relaxed text-muted">
            Atlas is not in the table. It ships a real migration linter and belongs here, but since
            v0.38 <code className="font-mono text-[13px] text-fg">atlas migrate lint</code> aborts
            without a paid account, so it had no chance to earn a number that a reader could
            reproduce.
          </p>
        </Block>

        <Block title="Run it yourself" last>
          <CodeBlock title="about six minutes" code={REPRODUCE} />
          <div className="mt-6 flex flex-wrap gap-x-5 gap-y-2">
            <a href={RESULTS} className="text-sm text-accent transition-colors hover:text-accent-hover">
              Full results, including every file and every tool
            </a>
            <a
              href={`${REPO}/tree/main/bench/corpus`}
              className="text-sm text-accent transition-colors hover:text-accent-hover"
            >
              The corpus
            </a>
            <a
              href={`${REPO}/blob/main/bench/rule-map.json`}
              className="text-sm text-accent transition-colors hover:text-accent-hover"
            >
              Rule classification
            </a>
          </div>
        </Block>
      </main>
      <Footer />
    </>
  );
}

function Block({
  title,
  children,
  last,
}: {
  title: string;
  children: React.ReactNode;
  last?: boolean;
}) {
  return (
    <section className={`py-12 md:py-16 ${last ? '' : 'border-b border-line-soft'}`}>
      <div className="mp-container">
        <h2 className="mb-6 text-xl font-semibold text-fg">{title}</h2>
        {children}
      </div>
    </section>
  );
}

function Table({ head, rows, mono }: { head: string[]; rows: string[][]; mono?: boolean }) {
  return (
    <div className="mp-scroll overflow-x-auto">
      <table className="w-full min-w-[620px] border-collapse text-left">
        <thead>
          <tr className="border-b border-line">
            {head.map((cell) => (
              <th key={cell} className="pb-2 pr-6 text-xs font-medium text-faint last:pr-0">
                {cell}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.join('|')} className="border-b border-line-soft last:border-b-0">
              {row.map((cell, i) => (
                <td
                  key={`${cell}-${i}`}
                  className={`py-3 pr-6 align-top last:pr-0 ${
                    i === 0 || mono || /^[\d/]/.test(cell)
                      ? 'font-mono text-[13px] text-fg'
                      : 'text-[13px] text-muted'
                  }`}
                >
                  {cell}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
